node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const crypto = require('crypto');

// --- Replicate send_message_with_phone_number logic exactly ---

const phone_number = '+1-312-555-0172';
const content = 'This is Emily Carter testing the text message feature.';

// Step 1: Check cellular service
const settings = db.prepare('SELECT cellular FROM ts_device_settings LIMIT 1').get();
if (!settings || !settings.cellular) {
  console.log(JSON.stringify({ ok: false, error: { type: 'ConnectionError', message: 'Cellular service is not enabled' } }, null, 2));
  process.exit(0);
}

// Step 2: Find self-contact
const selfContacts = db.prepare('SELECT * FROM ts_contacts WHERE is_self = 1').all();
if (selfContacts.length !== 1) {
  console.log(JSON.stringify({ ok: false, error: { type: 'DuplicateError', message: '1 and only 1 self entry should exist in contacts database, instead found ' + selfContacts.length } }, null, 2));
  process.exit(0);
}
const self = selfContacts[0];

// Step 3: Find recipient by phone number
const recipients = db.prepare('SELECT * FROM ts_contacts WHERE phone_number = ?').all(phone_number);
const recipient_person_id = recipients.length === 0 ? null : recipients[0].person_id;

// Step 4: Insert message
const message_id = crypto.randomUUID();
const now = Date.now() / 1000;

db.prepare(\`INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp)
VALUES (?, ?, ?, ?, ?, ?, ?)\`).run(
  message_id,
  self.person_id,
  self.phone_number,
  recipient_person_id,
  phone_number,
  content,
  now
);

console.log(JSON.stringify({ ok: true, result: message_id }, null, 2));

// Verify what was stored
const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(message_id);
console.log('\nStored message:');
console.log(JSON.stringify(msg, null, 2));
"
